/// Upstream /^\p{RGI_Emoji}$/v: whole-string RGI emoji membership.
pub(crate) fn is_rgi_emoji(segment: &str) -> bool {
    fn multi() -> &'static [&'static str] {
        static SET: OnceLock<&'static [&'static str]> = OnceLock::new();
        SET.get_or_init(|| RGI_MULTI)
    }
    let mut chars = segment.chars();
    if let Some(first) = chars.next() {
        if chars.next().is_none() {
            let cp_value = first as u32;
            return RGI_SINGLE
                .binary_search_by_key(&cp_value, |&(probe, _)| probe)
                .is_ok();
        }
    }
    multi().binary_search(&segment).is_ok()
}
